Verification task in the repository /dayjs (JavaScript date library). Do NOT edit any repository source files or pre-existing tests. Only run commands and (optionally) create then delete a temporary throwaway test file.

Context: a fix was just applied to /dayjs/src/plugin/timezone/index.js in `d.tz`:
```js
  d.tz = function (input, timezone) {
    const previousOffset = tzOffset(+d(), timezone)
    if (typeof input !== 'string') {
      // timestamp, js Date, Day.js object
      return d(input).tz(timezone)
    }
    const localTs = d.utc(input).valueOf()
    const [targetTs, targetOffset] = fixOffset(localTs, previousOffset, timezone)
    const ins = d(targetTs).utcOffset(targetOffset)
    return ins
  }
```

